import { expect, it } from "vitest"
import { randomBytes } from "node:crypto"
import { protectWindows } from "./credential-protection"

// Uses newly generated bytes only. No existing Windows credential is queried.
it.skipIf(process.platform !== "win32")(
  "round trips binary credentials through native CurrentUser DPAPI in separate processes",
  async () => {
    const plain = Buffer.concat([Buffer.from([0, 255, 10]), randomBytes(256)])
    try {
      const cipher = await protectWindows(plain, false)
      expect(cipher.length).toBeGreaterThan(plain.length)
      expect(cipher.includes(plain)).toBe(false)
      const restored = await protectWindows(cipher, true)
      try {
        expect(restored.equals(plain)).toBe(true)
      } finally {
        restored.fill(0)
      }
    } finally {
      plain.fill(0)
    }
  },
  40_000
)
